using System;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SpectralHarvesterOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/SpectralHarvesterOmenData")]
public class SpectralHarvesterOmenData : OnPlayerCorruptUseBattleActionOmenData
{
	private const string increaseThisCounterForCorruptionReceivedID = "IncreaseThisCounterForCorruptionReceived";

	[NonSerialized]
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		base.Initialize(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.SpectralHarvesterOmenActive = true;
	}

	protected override void ActivateOmenWithCorruptAmount(int corruptAmount)
	{
		int num = counter + corruptAmount;
		int timesToTrigger = Mathf.FloorToInt((float)num / (float)TriggerAmount);
		for (int i = 0; i < timesToTrigger; i++)
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
		}
		if (timesToTrigger > 0)
		{
			InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
			{
				OmenLogic.ActivateOmen(BattleAction, ActionValue * timesToTrigger, null, null);
			});
		}
		counter = num - timesToTrigger * TriggerAmount;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.SpectralHarvesterOmenActive = false;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetWheneverCorruptEnemyChantLocalized() + base.localizationManager.GetLocalizedString("IncreaseThisCounterForCorruptionReceived") + "\n" + Smart.Format(GetCorruptEnemyChantWithCounterTextWithCheckCounterKept(), TriggerAmount, GetOmenConvertedDescriptionBattleAction().LowercaseFirst());
	}
}
